import{_ as i,C as r,o as n,c as d,ao as s,j as a,a as l,E as o,w as c}from"./chunks/framework.B4BvXMeI.js";const M=JSON.parse('{"title":"Package","description":"","frontmatter":{},"headers":[],"relativePath":"reference/package.md","filePath":"reference/package.md","lastUpdated":null}'),p={name:"reference/package.md"},g={class:"jldocstring custom-block",open:""};function h(m,e,u,f,k,_){const t=r("Badge");return n(),d("div",null,[e[4]||(e[4]=s('<h1 id="Package" tabindex="-1">Package <a class="header-anchor" href="#Package" aria-label="Permalink to &quot;Package {#Package}&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Start here</p><p><code>DRModels</code> is the package module. For fitting choices, begin with <a href="./../capabilities">What can I fit today?</a>; for runnable syntax, use <a href="./../getting-started">Getting started</a>. This page documents the module overview rather than making a package-wide performance claim.</p></div>',2)),a("details",g,[a("summary",null,[e[0]||(e[0]=a("a",{id:"DRModels",href:"#DRModels"},[a("span",{class:"jlbinding"},"DRModels")],-1)),e[1]||(e[1]=l()),o(t,{type:"info",class:"jlObjectType jlModule",text:"Module"})]),e[3]||(e[3]=s('<div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DRModels</span></span></code></pre></div><p><code>DRModels.jl</code> — a Julia engine for distributional regression models, the Julia twin of the R package <strong>drmTMB</strong>. Mirrors the gllvmTMB → GLLVModels.jl move.</p><p>The package covers univariate and bivariate distributional regression across some twenty response families, with random, phylogenetic, spatial, pedigree and supplied-matrix structure. Its origin is the <strong>q=4 phylogenetic bivariate location–scale model (PLSM)</strong> — the selling-point model of drmTMB (Nakagawa et al. 2025 MEE, Model 5). That marginal is a sparse <strong>augmented-state Laplace approximation</strong> with an <strong>exact O(p) gradient</strong> (implicit-function / TMB-style, via Takahashi selected inverse — never forms a dense p×p Σ_phy), optimised by LBFGS with a fast-path-then-robust mode-finder.</p><p>For what is implemented and how far each route is tested, see the capability matrix in the documentation. Measured comparisons against drmTMB include their run conditions in <code>report/comparison-grid.md</code>; they are specific to the model and data measured and are deliberately not quoted as package-wide figures here.</p><p>The engine retains the proof-of-concept&#39;s script-style organisation. Inference provides Wald, profile, and parametric-bootstrap intervals. <strong>Public:</strong> opt-in REML (<code>drm(method = :REML)</code>; its restricted correction covers all four among-axis axes) and the conjugate-EM Gaussian phylo-mean solver (<code>algorithm = :em</code>). A natural-gradient EM implementation failed the required likelihood-parity check on <code>q4_p100</code>, so <code>algorithm = :natgrad</code> is not exposed; the reusable Fisher metric is retained as engine infrastructure. <strong>Experimental prototypes are not wired:</strong> SQUAREM EM, trust-region and line-search E-steps, dense q=4 EM, and warm-start variants. Do not treat them as the public REML or <code>:em</code> surface.</p>',5)),o(t,{type:"info",class:"source-link",text:"source"},{default:c(()=>[...e[2]||(e[2]=[a("a",{href:"https://github.com/itchyshin/DRModels.jl/blob/d6a1e41e56418c11e4908316d1173f47ebe1f4bd/src/DRModels.jl#L1-L31",target:"_blank",rel:"noreferrer"},"source",-1)])]),_:1})])])}const v=i(p,[["render",h]]);export{M as __pageData,v as default};
